// Temporary verification driver (deleted after use). Not part of the repo.
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { serveStatic, launchChromium, visitBreakpoint } from './harness/playwright/serve-and-visit.mjs';
import { assertResponsive } from './harness/gate/check-responsive.mjs';

const ROOT = dirname(fileURLToPath(import.meta.url));
const DIST = join(ROOT, 'dist', 'angular-jig', 'browser');
const ROUTES = ['dashboard', 'roster', 'detail/11', 'missions', 'threats', 'recruit', 'settings'];
const errors = [];
const log = (msg) => console.log(msg);
const expect = (cond, msg) => {
  if (!cond) throw new Error('EXPECT FAILED: ' + msg);
  log('ok: ' + msg);
};

const srv = await serveStatic(DIST, { spaFallback: true });
const browser = await launchChromium();
try {
  // 1. Responsive, every screen, every width.
  for (const route of ROUTES) {
    const { failures } = await assertResponsive({ origin: srv.origin, route, browser });
    log(`responsive /${route}: ${failures.length ? JSON.stringify(failures.slice(0, 6)) : 'pass'}`);
  }

  // 2. Interactions across one live session so the shared service is what carries state between screens.
  const context = await browser.newContext({ viewport: { width: 1280, height: 900 } });
  const page = await context.newPage();
  page.on('pageerror', (e) => errors.push('pageerror: ' + e.message));
  page.on('console', (m) => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
  const nav = (label) => page.locator(`a[data-sidebar="menu-button"], a[hlmSidebarMenuButton], nav[aria-label="Primary"] a`).filter({ hasText: label }).first().click();

  await page.goto(`${srv.origin}/detail/11`, { waitUntil: 'networkidle' });
  await page.getByRole('button', { name: 'Edit', exact: true }).click();
  await page.waitForTimeout(300);
  await page.locator('#hero-name').fill('');
  await page.getByRole('button', { name: 'Save changes' }).click();
  await page.waitForTimeout(300);
  expect(await page.getByText('Codename is required').count() > 0, 'empty codename shows the schema message');

  // Open a select, confirm the portal lists its options, then close it.
  await page.locator('#hero-power-class').click();
  await page.waitForTimeout(300);
  expect(await page.getByRole('option').count() >= 7, 'power class select lists its seven options');
  await page.keyboard.press('Escape');
  await page.waitForTimeout(200);

  await page.locator('#hero-name').fill('Grond Prime');
  await page.locator('#hero-power').fill('55');
  await page.getByRole('button', { name: 'Save changes' }).click();
  await page.waitForTimeout(300);
  expect(await page.getByText('Saved changes to Grond Prime.').count() > 0, 'save shows the notice');

  await nav('Roster');
  await page.waitForTimeout(300);
  expect(await page.getByRole('link', { name: 'Grond Prime' }).count() > 0, 'roster reflects the edited codename');

  await nav('Dashboard');
  await page.waitForTimeout(300);
  expect(await page.getByText('Grond Prime').count() > 0, 'dashboard reflects the edited codename');

  // Recruit a hero, then the new record opens on detail.
  await nav('Recruit');
  await page.waitForTimeout(300);
  await page.getByRole('button', { name: 'Enlist hero' }).click();
  await page.waitForTimeout(300);
  expect(await page.getByText('Codename is required').count() > 0, 'recruit validates before creating');
  await page.locator('#hero-name').fill('Comet Vance');
  await page.locator('#hero-alias').fill('Test Alias');
  await page.locator('#hero-notes').fill('Test dossier notes.');
  await page.getByRole('button', { name: 'Enlist hero' }).click();
  await page.waitForURL(/\/detail\/13$/, { timeout: 5000 });
  expect(page.url().endsWith('/detail/13'), 'recruit opens the new record on detail');

  await nav('Missions');
  await page.waitForTimeout(300);
  expect(await page.getByRole('link', { name: 'Comet Vance' }).count() > 0, 'missions lists the recruited hero');

  await nav('Threats');
  await page.waitForTimeout(300);
  expect(await page.getByText('Tiers covered').count() > 0, 'threats renders stats');

  // Retire via the confirmation dialog on detail, which must remove the record and leave the roster.
  await page.goto(`${srv.origin}/detail/13`, { waitUntil: 'networkidle' }).catch(() => {});
  await nav('Roster');
  await page.waitForTimeout(300);
  await page.getByRole('link', { name: 'Comet Vance' }).click();
  await page.waitForTimeout(300);
  await page.getByRole('button', { name: 'Retire', exact: true }).click();
  await page.waitForTimeout(300);
  await page.getByRole('button', { name: 'Retire hero' }).click();
  await page.waitForTimeout(400);
  expect(page.url().endsWith('/roster'), 'retire navigates back to the roster');
  expect(await page.getByRole('link', { name: 'Comet Vance' }).count() === 0, 'retired hero is gone from the roster');

  // Settings: theme choice applies to the document.
  await nav('Settings');
  await page.waitForTimeout(300);
  await page.locator('#settings-theme').click();
  await page.waitForTimeout(300);
  await page.getByRole('option', { name: 'Dark' }).click();
  await page.waitForTimeout(300);
  expect(await page.evaluate(() => document.documentElement.classList.contains('dark')), 'settings dark theme applies');

  // Bell goes to the threat alerts.
  await page.getByRole('link', { name: /Notifications/ }).click();
  await page.waitForTimeout(300);
  expect(page.url().endsWith('/threats'), 'bell opens threat alerts');

  // Mobile drawer at 375: trigger opens the sidebar and it becomes visible.
  const mobile = await context.newPage();
  mobile.on('pageerror', (e) => errors.push('mobile pageerror: ' + e.message));
  await mobile.setViewportSize({ width: 375, height: 800 });
  await mobile.goto(`${srv.origin}/roster`, { waitUntil: 'networkidle' });
  await mobile.locator('button[data-sidebar="trigger"]').click();
  await mobile.waitForTimeout(400);
  expect(await mobile.getByRole('link', { name: 'Threats' }).first().isVisible(), 'mobile drawer opens with nav visible');
} catch (e) {
  log(String(e && e.message ? e.message : e));
  process.exitCode = 1;
} finally {
  log(`runtime errors observed: ${errors.length}`);
  for (const e of errors.slice(0, 20)) log('  ' + e.slice(0, 300));
  await browser.close();
  await srv.close();
}

