// Temporary probe (deleted after use). Not part of the repo.
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { serveStatic, launchChromium } from './harness/playwright/serve-and-visit.mjs';

const ROOT = dirname(fileURLToPath(import.meta.url));
const DIST = join(ROOT, 'dist', 'angular-jig', 'browser');
const srv = await serveStatic(DIST, { spaFallback: true });
const browser = await launchChromium();
try {
  const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
  await page.goto(`${srv.origin}/roster`, { waitUntil: 'networkidle' });
  const info = await page.evaluate(() => {
    const out = [];
    for (const el of document.querySelectorAll('a.ring-sidebar-ring')) {
      const cs = getComputedStyle(el);
      const r = el.getBoundingClientRect();
      out.push({
        cls: el.className.slice(0, 200),
        text: el.textContent.trim(),
        rect: [Math.round(r.left), Math.round(r.top), Math.round(r.width), Math.round(r.height)],
        scroll: [el.scrollWidth, el.clientWidth, el.scrollHeight, el.clientHeight],
        overflow: [cs.overflowX, cs.overflowY],
        boxShadow: cs.boxShadow.slice(0, 120),
        outline: cs.outline.slice(0, 80),
      });
    }
    return out;
  });
  console.log(JSON.stringify(info.slice(0, 2), null, 2));
  const parent = await page.evaluate(() => {
    const el = document.querySelector('a.ring-sidebar-ring');
    const p = el.parentElement;
    const cs = getComputedStyle(p);
    return { tag: p.tagName, cls: p.className.slice(0, 160), overflow: [cs.overflowX, cs.overflowY], scroll: [p.scrollWidth, p.clientWidth] };
  });
  console.log(JSON.stringify(parent));
} finally {
  await browser.close();
  await srv.close();
}

