import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { serveStatic, launchChromium } from './harness/playwright/serve-and-visit.mjs';

const ROOT = dirname(fileURLToPath(import.meta.url));
const DIST = join(ROOT, 'dist', 'angular-jig', 'browser');
const srv = await serveStatic(DIST, { spaFallback: true });
const browser = await launchChromium();
try {
  const page = await browser.newPage({ viewport: { width: 375, height: 800 } });
  await page.goto(`${srv.origin}/roster`, { waitUntil: 'networkidle' });
  const info = await page.evaluate(() => {
    const box = (el) => {
      if (!el) return null;
      const r = el.getBoundingClientRect();
      return { cls: (el.className?.baseVal ?? el.className ?? '').toString().slice(0, 60), tag: el.tagName, l: Math.round(r.left), t: Math.round(r.top), w: Math.round(r.width), h: Math.round(r.height), pos: getComputedStyle(el).position };
    };
    const trig = document.querySelector('button[data-sidebar="trigger"]');
    const chain = [];
    for (let e = trig; e && chain.length < 8; e = e.parentElement) chain.push(box(e));
    return {
      trigger: box(trig),
      triggerChain: chain,
      topbar: box(document.querySelector('.app__topbar')),
      start: box(document.querySelector('.app__start')),
      actions: box(document.querySelector('.app__actions')),
      search: box(document.querySelector('.app__search')),
      sidebar: box(document.querySelector('hlm-sidebar')),
      inset: box(document.querySelector('main')),
    };
  });
  console.log(JSON.stringify(info, null, 1));
} finally {
  await browser.close();
  await srv.close();
}

